-- Workspaces, roles and the data model behind the new design.
--
-- Hand-edited (generated by `prisma migrate diff`, then corrected). Prisma would have:
--   * recreated "ExperimentStatus" and cast ARCHIVED rows to a value that no longer exists, so the
--     enum value is renamed in place instead (ARCHIVED -> COMPLETED; every row keeps its meaning);
--   * dropped "stoppedAt" and added an empty "endedAt", so the column is renamed instead;
--   * added NOT NULL "workspaceId" columns to non-empty tables, which fails, and dropped "userId"
--     with the only record of who owned what. Instead every existing user gets a workspace and an
--     OWNER membership, websites and the Sheets grant are moved into it, and only then is the
--     column made NOT NULL and "userId" dropped;
--   * added a NOT NULL "name" to experiment_variants with no value, so it is added nullable,
--     backfilled from the position ("Variant A", "Variant B", ...) and then made NOT NULL.
-- The partial / expression unique indexes at the end cannot be expressed in schema.prisma.
-- CreateEnum
CREATE TYPE "ExperimentType" AS ENUM ('SPLIT_URL', 'AB_TEST');

-- CreateEnum
CREATE TYPE "DeviceType" AS ENUM ('DESKTOP', 'MOBILE', 'TABLET');

-- CreateEnum
CREATE TYPE "MemberRole" AS ENUM ('OWNER', 'ADMIN', 'EDITOR', 'VIEWER');

-- CreateEnum
CREATE TYPE "ExperimentActivityType" AS ENUM ('CREATED', 'LAUNCHED', 'PAUSED', 'RESUMED', 'ENDED', 'EDITED', 'RESULT_READY');

-- CreateEnum
CREATE TYPE "NotificationKind" AS ENUM ('RESULT_READY', 'TRACKING_STOPPED', 'SHEETS_SYNC_FAILED', 'EXPERIMENT_PAUSED');

-- CreateEnum
CREATE TYPE "TrackingCheckResult" AS ENUM ('OK', 'MISSING', 'ERROR');

-- AlterEnum (hand-written: rename in place, so ARCHIVED rows become COMPLETED)
ALTER TYPE "ExperimentStatus" RENAME VALUE 'ARCHIVED' TO 'COMPLETED';

