ADD COLUMN     "colorIndex" INTEGER NOT NULL DEFAULT 1,
ADD COLUMN     "name" TEXT,
ALTER COLUMN "url" DROP NOT NULL;

-- Backfill (hand-written): names from position, colour slots cycling 1-4 in position order.
UPDATE "experiment_variants"
SET "name" = CASE WHEN "position" BETWEEN 1 AND 26
                  THEN 'Variant ' || chr(64 + "position")
                  ELSE 'Variant ' || "position"::text END,
    "colorIndex" = (("position" - 1) % 4 + 4) % 4 + 1;
ALTER TABLE "experiment_variants" ALTER COLUMN "name" SET NOT NULL;

