-- ---------------------------------------------------------------------------
-- Data migration (hand-written): one workspace + OWNER membership per existing user.
-- ---------------------------------------------------------------------------

CREATE TEMPORARY TABLE "_user_workspace" AS
SELECT u."id" AS "userId",
       'c' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 24) AS "workspaceId",
       'c' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 24) AS "membershipId",
       left(split_part(coalesce(nullif(btrim(u."name"), ''), split_part(u."email", '@', 1)), ' ', 1), 64)
         || E'\u2019s workspace' AS "name",
       u."createdAt"
FROM "users" u;

INSERT INTO "workspaces" ("id", "name", "createdAt", "updatedAt")
SELECT "workspaceId", "name", "createdAt", CURRENT_TIMESTAMP FROM "_user_workspace";

INSERT INTO "memberships" ("id", "workspaceId", "userId", "role", "createdAt", "updatedAt")
SELECT "membershipId", "workspaceId", "userId", 'OWNER', "createdAt", CURRENT_TIMESTAMP
FROM "_user_workspace";

UPDATE "users" u SET "currentWorkspaceId" = m."workspaceId"
FROM "_user_workspace" m WHERE m."userId" = u."id";

-- Websites move into their owner's workspace; the owner is recorded as the creator.
UPDATE "websites" w SET "workspaceId" = m."workspaceId", "createdById" = w."userId"
FROM "_user_workspace" m WHERE m."userId" = w."userId";

-- The Sheets grant moves to the granting user's workspace; they remain its connector.
UPDATE "sheets_connections" c SET "workspaceId" = m."workspaceId", "connectedById" = c."userId"
FROM "_user_workspace" m WHERE m."userId" = c."userId";

-- Every experiment was created by its website's owner — there was nobody else who could.
UPDATE "experiments" e SET "createdById" = w."userId"
FROM "websites" w WHERE w."id" = e."websiteId";

-- Activity history reconstructed from the timestamps that already exist.
INSERT INTO "experiment_activities" ("id", "experimentId", "type", "actorId", "createdAt")
SELECT 'c' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 24), e."id", 'CREATED', e."createdById", e."createdAt"
FROM "experiments" e;
INSERT INTO "experiment_activities" ("id", "experimentId", "type", "actorId", "createdAt")
SELECT 'c' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 24), e."id", 'LAUNCHED', e."createdById", e."publishedAt"
FROM "experiments" e WHERE e."publishedAt" IS NOT NULL;
INSERT INTO "experiment_activities" ("id", "experimentId", "type", "actorId", "createdAt")
SELECT 'c' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 24), e."id", 'ENDED', e."createdById", e."endedAt"
FROM "experiments" e WHERE e."status" = 'COMPLETED' AND e."endedAt" IS NOT NULL;

ALTER TABLE "websites" ALTER COLUMN "workspaceId" SET NOT NULL;
ALTER TABLE "sheets_connections" ALTER COLUMN "workspaceId" SET NOT NULL;
ALTER TABLE "websites" DROP COLUMN "userId";
ALTER TABLE "sheets_connections" DROP COLUMN "userId";
DROP TABLE "_user_workspace";

-- Project names become unique per workspace (case-insensitively). Older data was never held to
-- that, so later duplicates get a numeric suffix rather than failing the migration. Duplicate
-- domains cannot be renamed safely, so those stop the migration with a readable error.
UPDATE "websites" w SET "name" = left(w."name", 54) || ' (' || d."n" || ')'
FROM (SELECT "id", row_number() OVER (PARTITION BY "workspaceId", lower("name") ORDER BY "createdAt", "id") AS "n"
      FROM "websites") d
WHERE d."id" = w."id" AND d."n" > 1;

DO $$
DECLARE dup text;
BEGIN
  SELECT string_agg(DISTINCT "domain", ', ') INTO dup FROM (
    SELECT "domain" FROM "websites" GROUP BY "workspaceId", "domain" HAVING count(*) > 1) x;
  IF dup IS NOT NULL THEN
    RAISE EXCEPTION 'Two websites of one account share a domain (%). Merge or delete one, then re-run.', dup;
  END IF;
END $$;

