-- ---------------------------------------------------------------------------
-- Constraints schema.prisma cannot express (hand-written).
-- ---------------------------------------------------------------------------

-- Exactly one owner per workspace (at most one here; "at least one" is a service rule).
CREATE UNIQUE INDEX "memberships_one_owner" ON "memberships"("workspaceId") WHERE "role" = 'OWNER';

-- At most one pending invite per address per workspace. Accepted and revoked invites are history.
CREATE UNIQUE INDEX "workspace_invites_pending" ON "workspace_invites"("workspaceId", "email")
  WHERE "acceptedAt" IS NULL AND "revokedAt" IS NULL;

-- RESULT_READY is recorded at most once per experiment.
CREATE UNIQUE INDEX "experiment_activities_result_once" ON "experiment_activities"("experimentId")
  WHERE "type" = 'RESULT_READY';

-- Project names are unique per workspace, ignoring case.
CREATE UNIQUE INDEX "websites_ws_name_ci" ON "websites"("workspaceId", lower("name"));
